#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
static uint32_t get32(unsigned char *p){return ((uint32_t)p[0]<<24)|((uint32_t)p[1]<<16)|((uint32_t)p[2]<<8)|p[3];}
static void put32(uint32_t n){unsigned char b[]={n>>24,n>>16,n>>8,n};fwrite(b,1,4,stdout);}
int main(int argc,char **argv){unsigned char header[4],body[65536];const char *mode=argc>1 ? argv[1] : "bad-name";while(fread(header,1,4,stdin)==4){uint32_t n=get32(header);if(n<1||n>sizeof(body)||fread(body,1,n,stdin)!=n)return 1;unsigned type=body[0];if(type==1){put32(5);fputc(2,stdout);put32(3);}else{if(n<5)return 1;uint32_t id=get32(body+1);if(!strcmp(mode,"bad-length")){put32(16*1024*1024+1);}else if(type==16||type==19){const unsigned char invalid[]={255},nul[]={'/','a',0,'b'};const unsigned char *path=(!strcmp(mode,"link-count")||!strcmp(mode,"link-trailing")) ? (const unsigned char*)"a" : invalid;uint32_t size=1;if(!strcmp(mode,"canonical-empty")||!strcmp(mode,"link-empty"))size=0;else if((!strcmp(mode,"canonical-nul")||!strcmp(mode,"link-nul"))){path=nul;size=sizeof(nul);}else if((!strcmp(mode,"canonical-long")||!strcmp(mode,"link-long")))size=65537;put32(1+4+4+4+size+4+4+(!strcmp(mode,"link-trailing")));fputc(104,stdout);put32(id);put32(!strcmp(mode,"link-count") ? 2 : 1);put32(size);if((!strcmp(mode,"canonical-long")||!strcmp(mode,"link-long"))){for(uint32_t i=0;i<size;i++)fputc('a',stdout);}else fwrite(path,1,size,stdout);put32(0);put32(0);if(!strcmp(mode,"link-trailing"))fputc(0,stdout);}else if(type==11){put32(10);fputc(102,stdout);put32(id+(!strcmp(mode,"bad-id")));put32(1);fputc('h',stdout);}else if(type==12){const char *name="../escape";put32(1+4+4+4+strlen(name)+4+4);fputc(104,stdout);put32(id);put32(1);put32(strlen(name));fwrite(name,1,strlen(name),stdout);put32(0);put32(0);}else{put32(17);fputc(101,stdout);put32(id);put32(0);put32(0);put32(0);}}fflush(stdout);}return 0;}
